// Controlled tiny image files; JPEG/AVIF were encoded from the local PNG fixture.
export const AI_CHAT_IMAGE_SAMPLES: ReadonlyArray<{
  mimeType: string;
  extension: string;
  base64: string;
}> = [
  {
    mimeType: 'image/png',
    extension: 'png',
    base64:
      'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEUlEQVR4nGNgYPgPBCACyAIANdgH+Vq2rHoAAAAASUVORK5CYII='
  },
  {
    mimeType: 'image/jpeg',
    extension: 'jpg',
    base64:
      ''
  },
  {
    mimeType: 'image/gif',
    extension: 'gif',
    base64: 'R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'
  },
  {
    mimeType: 'image/webp',
    extension: 'webp',
    base64: 'UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AAAAAA'
  },
  {
    mimeType: 'image/avif',
    extension: 'avif',
    base64:
      ''
  },
  {
    mimeType: 'image/svg+xml',
    extension: 'svg',
    base64:
      'PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjEiPjxyZWN0IHdpZHRoPSIxIiBoZWlnaHQ9IjEiIGZpbGw9ImJsdWUiLz48L3N2Zz4='
  }
];

export const imageBytes = (base64: string) => Uint8Array.from(Buffer.from(base64, 'base64'));

export function imageSample(extension: string) {
  const sample = AI_CHAT_IMAGE_SAMPLES.find((item) => item.extension === extension);
  if (!sample) throw new Error('Missing controlled image sample');
  return sample;
}
